                    OahuWriter::writeString,
                )
                val middleName = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_MIDDLE_NAME,
                    IdentitySectionContract.MEMBER_EDIT_MIDDLE_NAME,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val lastName = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_LAST_NAME,
                    IdentitySectionContract.MEMBER_EDIT_LAST_NAME,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val username = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_USERNAME,
                    IdentitySectionContract.MEMBER_EDIT_USERNAME,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val company = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_COMPANY,
                    IdentitySectionContract.MEMBER_EDIT_COMPANY,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val ssn = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_SSN,
                    IdentitySectionContract.MEMBER_EDIT_SSN,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val passportNumber = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_PASSPORT_NUMBER,
                    IdentitySectionContract.MEMBER_EDIT_PASSPORT_NUMBER,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val licenseNumber = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_LICENSE_NUMBER,
                    IdentitySectionContract.MEMBER_EDIT_LICENSE_NUMBER,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val email = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_EMAIL,
                    IdentitySectionContract.MEMBER_EDIT_EMAIL,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val phone = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_PHONE,
                    IdentitySectionContract.MEMBER_EDIT_PHONE,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val address1 = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_ADDRESS1,
                    IdentitySectionContract.MEMBER_EDIT_ADDRESS1,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val address2 = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_ADDRESS2,
                    IdentitySectionContract.MEMBER_EDIT_ADDRESS2,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val address3 = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_ADDRESS3,
                    IdentitySectionContract.MEMBER_EDIT_ADDRESS3,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val city = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_CITY,
                    IdentitySectionContract.MEMBER_EDIT_CITY,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val state = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_STATE,
                    IdentitySectionContract.MEMBER_EDIT_STATE,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val postalCode = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_POSTAL_CODE,
                    IdentitySectionContract.MEMBER_EDIT_POSTAL_CODE,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val country = connection.subscribeEditable(
                    IdentitySectionContract.STREAM_COUNTRY,
                    IdentitySectionContract.MEMBER_EDIT_COUNTRY,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val focus = OahuEvents<Int>()
                connection.subscribe(IdentitySectionContract.STREAM_FOCUS, OahuReader::readInt, focus::emit)
                return IdentitySectionModel(
                    connection,
                    copy,
                    title,
                    firstName,
                    middleName,
                    lastName,
                    username,
                    company,
                    ssn,
                    passportNumber,
                    licenseNumber,
                    email,
                    phone,
                    address1,
                    address2,
                    address3,
                    city,
                    state,
                    postalCode,
                    country,
                    focus,
                )
            } catch (failure: Throwable) {
                connection.close()
                throw failure
            }
        }

        /**
         * The real model over an [OahuPreviewPort] that replays these values. Methods without handlers
         * have no effect. [configure] runs on a [Preview] before the model connects.
         */
        public fun preview(
            copy: IdentitySectionCopy,
            title: Int,
            firstName: String,
            middleName: String,
            lastName: String,
            username: String,
            company: String,
            ssn: String,
            passportNumber: String,
            licenseNumber: String,
            email: String,
            phone: String,
            address1: String,
            address2: String,
            address3: String,
            city: String,
            state: String,
            postalCode: String,
            country: String,
            configure: Preview.() -> Unit = {},
        ): IdentitySectionModel {
            val port = OahuPreviewPort(IdentitySectionContract.NAME, IdentitySectionContract.HASH)
            port.setState(IdentitySectionContract.STREAM_COPY) { IdentitySectionCopyOahuCodec.writeIdentitySectionCopy(it, copy) }
            port.setState(IdentitySectionContract.STREAM_TITLE) { it.writeInt(title) }
            port.setState(IdentitySectionContract.STREAM_FIRST_NAME) { it.writeString(firstName) }
            port.setState(IdentitySectionContract.STREAM_MIDDLE_NAME) { it.writeString(middleName) }
            port.setState(IdentitySectionContract.STREAM_LAST_NAME) { it.writeString(lastName) }
            port.setState(IdentitySectionContract.STREAM_USERNAME) { it.writeString(username) }
            port.setState(IdentitySectionContract.STREAM_COMPANY) { it.writeString(company) }
            port.setState(IdentitySectionContract.STREAM_SSN) { it.writeString(ssn) }
            port.setState(IdentitySectionContract.STREAM_PASSPORT_NUMBER) { it.writeString(passportNumber) }
            port.setState(IdentitySectionContract.STREAM_LICENSE_NUMBER) { it.writeString(licenseNumber) }
            port.setState(IdentitySectionContract.STREAM_EMAIL) { it.writeString(email) }
            port.setState(IdentitySectionContract.STREAM_PHONE) { it.writeString(phone) }
            port.setState(IdentitySectionContract.STREAM_ADDRESS1) { it.writeString(address1) }
            port.setState(IdentitySectionContract.STREAM_ADDRESS2) { it.writeString(address2) }
            port.setState(IdentitySectionContract.STREAM_ADDRESS3) { it.writeString(address3) }
            port.setState(IdentitySectionContract.STREAM_CITY) { it.writeString(city) }
            port.setState(IdentitySectionContract.STREAM_STATE) { it.writeString(state) }
            port.setState(IdentitySectionContract.STREAM_POSTAL_CODE) { it.writeString(postalCode) }
            port.setState(IdentitySectionContract.STREAM_COUNTRY) { it.writeString(country) }
            val preview = Preview(port)
            // Edits are accepted as proposed until configure answers them (docs/editable.md §5).
            preview.onEditTitle { it }
            preview.onEditFirstName { it }
            preview.onEditMiddleName { it }
            preview.onEditLastName { it }
            preview.onEditUsername { it }
            preview.onEditCompany { it }
            preview.onEditSsn { it }
            preview.onEditPassportNumber { it }
            preview.onEditLicenseNumber { it }
            preview.onEditEmail { it }
            preview.onEditPhone { it }
            preview.onEditAddress1 { it }
            preview.onEditAddress2 { it }
            preview.onEditAddress3 { it }
            preview.onEditCity { it }
            preview.onEditState { it }
            preview.onEditPostalCode { it }
            preview.onEditCountry { it }
            preview.configure()
            return connect(port)
        }
    }
}

